import styled from '@emotion/styled';
import { Button } from 'components/UI';

interface StyledExpandProps {
  $disabledState?: boolean;
}

export const StyledExpand = styled(Button, {
  shouldForwardProp: (prop) => prop !== '$disabledState',
})<StyledExpandProps>(({ $disabledState }) => ({
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '40px',
  minWidth: '40px',
  height: '40px',
  maxHeight: '40px',
  borderRadius: '50%',
  border: '1px solid #141414',
  cursor: 'pointer',
  background: 'white',

  '&:active svg': {
    color: '#14141466',
  },

  ...($disabledState && {
    border: '1px solid #141414 !important',
    background: 'white !important',
    opacity: 0.5,
    pointerEvents: 'none',
  }),
}));
